const REGISTRIES: Record<string, Registry> = {
  turkey: { config: TURKEY_CONFIG, meta: turkey.meta as RegistryMeta, rows: turkey.rows as RegistryRow[] },
  'south-korea': { config: KOREA_CONFIG, meta: korea.meta as RegistryMeta, rows: korea.rows as RegistryRow[] },
};

export const REGISTRY_SLUGS = Object.keys(REGISTRIES);

export function getRegistry(slug: string): Registry | undefined {
  return REGISTRIES[slug];
}

export interface RegionSummary {
  region: string;
  regionSlug: string;
  count: number;
  byCategory: Record<string, number>;
  /** True when the region is big enough to split into per-category pages. */
  split: boolean;
}

export function regionSummaries(slug: string): RegionSummary[] {
  const reg = getRegistry(slug);
  if (!reg) return [];
  const map = new Map<string, RegionSummary>();
  for (const r of reg.rows) {
    let s = map.get(r.regionSlug);
    if (!s) {
      s = { region: r.region, regionSlug: r.regionSlug, count: 0, byCategory: {}, split: false };
      map.set(r.regionSlug, s);
    }
    s.count += 1;
    s.byCategory[r.category] = (s.byCategory[r.category] || 0) + 1;
  }
  const out = Array.from(map.values());
  for (const s of out) s.split = s.count > reg.config.splitAbove;
  return out.sort((a, b) => b.count - a.count || a.region.localeCompare(b.region));
}

export function regionSummary(slug: string, regionSlug: string): RegionSummary | undefined {
  return regionSummaries(slug).find((r) => r.regionSlug === regionSlug);
}

export function rowsFor(slug: string, regionSlug: string, category?: string): RegistryRow[] {
  const reg = getRegistry(slug);
  if (!reg) return [];
  return reg.rows.filter((r) => r.regionSlug === regionSlug && (!category || r.category === category));
}

export function categoryLabel(slug: string, category: string): string {
  const reg = getRegistry(slug);
  return reg?.config.categories.find((c) => c.slug === category)?.label ?? category;
}

/** Order categories as the config lists them; unknown categories last. */
export function orderedCategories(slug: string, present: Iterable<string>): string[] {
  const reg = getRegistry(slug);
  if (!reg) return Array.from(present);
  const order = reg.config.categories.map((c) => c.slug);
  return Array.from(new Set(present)).sort((a, b) => {
    const ia = order.indexOf(a); const ib = order.indexOf(b);
    return (ia === -1 ? 99 : ia) - (ib === -1 ? 99 : ib);
  });
}

/** Group rows by district, largest first, then alphabetical by name inside. */
export function groupByDistrict(rows: RegistryRow[]): { district: string; rows: RegistryRow[] }[] {
  const map = new Map<string, RegistryRow[]>();
  for (const r of rows) {
    const key = r.district || 'District not stated';
    if (!map.has(key)) map.set(key, []);
    map.get(key)!.push(r);
  }
  return Array.from(map.entries())
    .map(([district, rs]) => ({ district, rows: rs.sort((a, b) => a.name.localeCompare(b.name)) }))
    .sort((a, b) => {
      if (a.district === 'District not stated') return 1;
      if (b.district === 'District not stated') return -1;
      return b.rows.length - a.rows.length || a.district.localeCompare(b.district);
    });
}

function fold(s: string): string {
  return s.replace(/ı/g, 'i').replace(/İ/g, 'I').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
}

/** Case- and accent-insensitive substring search over name, district, region and address. */
export function searchRegistry(slug: string, q: string, limit = 200): RegistryRow[] {
  const reg = getRegistry(slug);
  const needle = fold(q.trim());
  if (!reg || needle.length < 2) return [];
  const out: RegistryRow[] = [];
  for (const r of reg.rows) {
    if (fold(`${r.name} ${r.district} ${r.region} ${r.address}`).includes(needle)) {
      out.push(r);
      if (out.length >= limit) break;
    }
  }
  return out;
}

/**
 * Registry row ids that have a hand-researched ClinicProfile in the dossier.
 * A profile declares `registryMatch`: accent- and case-insensitive phrases that
 * must appear as whole words in the official row name (so "memorial" badges
 * every Memorial hospital, while "vera" does not catch "Dentavera").
 */
export function profiledRowIds(slug: string): Map<string, string> {
  const reg = getRegistry(slug);
  const dossier = DOSSIERS[slug];
  const out = new Map<string, string>();
  if (!reg || !dossier) return out;
  const patterns: { re: RegExp; name: string }[] = [];
  for (const c of dossier.clinics) {
    for (const n of c.registryMatch ?? []) {
      const esc = fold(n).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
      patterns.push({ re: new RegExp(`(^|[^a-z0-9])${esc}([^a-z0-9]|$)`), name: c.name });
    }
  }
  if (!patterns.length) return out;
  for (const r of reg.rows) {
    const name = fold(r.name);
    const hit = patterns.find((p) => p.re.test(name));
    if (hit) out.set(r.id, hit.name);
  }
  return out;
}

/** Paths the sitemap should advertise: the overview, every region and category page that clears the index bar. */
export function registryDirectoryPaths(minRows: number): string[] {
  const out: string[] = [];
  for (const slug of REGISTRY_SLUGS) {
    out.push(`/destinations/${slug}/directory`);
    for (const s of regionSummaries(slug)) {
      if (s.count >= minRows) out.push(`/destinations/${slug}/directory/${s.regionSlug}`);
      if (s.split) {
        for (const [cat, n] of Object.entries(s.byCategory)) {
          if (n >= minRows) out.push(`/destinations/${slug}/directory/${s.regionSlug}/${cat}`);
        }
      }
    }
  }
  return out;
}

/** Stable in-page anchor for a ClinicProfile on the hub (#clinic-<slug>). */
export function clinicAnchor(name: string): string {
  return 'clinic-' + fold(name).replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
}

export function formatCount(n: number): string {
  return n.toLocaleString('en-US');
}
